{
  "task_id": "UI_AGENTS_DEPLOY_VERIFY_v1",
  "role": "FrontOps",
  "goal": "Страница Agents работает на реальном API с кэшем SWR; билд/деплой корректен; мок-данных нет.",
  "stage0_context": {
    "action": "GET /api/v1/context/?task_description=UI Agents deploy & verify",
    "include_in_report": ["capsule_id","capsule_version","excerpt_200_400_chars"],
    "fallbacks": ["если 404 — сверка /openapi.json и локальный 127.0.0.1:8081"]
  },
  "inputs_contracts": {
    "api": [
      "GET /api/v1/agents/status?fresh=0|1",
      "POST /api/v1/agents/refresh"
    ],
    "ui_entry": "https://etl-tst.chococraft.ru/admin/agents (Basic Auth)",
    "wrappers_hint": "скрипты деплоя/сборки и пути получи из контекста ('ff-ui-deploy-safe' и пр.), запуск — без sudo",
    "secrets_hint": "BasicAuth для админки возьми из хранилища секретов/Кортекса (не хардкодить в коде/логе)"
  },
  "what_to_do": [
    "Построить UI и подготовить релизный dist.",
    "Задеплоить UI штатной обёрткой из контекста.",
    "Проверить, что страница /admin/agents отдается и React-приложение инициализируется (см. пруфы ниже).",
    "Проверить связку UI→API: status (fresh=0 и fresh=1) и кнопка 'Обновить'.",
    "Убедиться в отсутствии мок-текста и мок-флагов в итоговом бандле."
  ],
  "proof_pack": {
    "required": [
      "context_excerpt (источник + выдержка)",
      "build_artifacts: список файлов dist с хэшами (index.html, assets/*hash*.js|css)",
      "network_ok: успешный запрос UI→GET /api/v1/agents/status (200), затем POST /api/v1/agents/refresh и повторный GET с обновлённым as_of",
      "ui_alive: скриншот страницы /admin/agents после входа по Basic Auth (видны карточки агентов, бейдж 'as of', цвета статуса)",
      "no_mocks: подтверждение, что строка 'loaded with mock data' отсутствует в финальных JS/CSS; флаги VITE_*_MOCKS=false",
      "perf_note: время ответа кэшированного GET /agents/status < 100 мс (по измерениям на стороне бэкенда/логов)"
    ],
    "nice_to_have": [
      "консоль UI без ошибок (выскажи итог: errors=0|>0)",
      "скрин 'до/после' на карточке любого агента после нажатия 'Обновить' (as_of изменился)"
    ]
  },
  "report": {
    "name": "REPORT_Agents_Cache_UI_Deploy_v1",
    "shape": {
      "env": "test",
      "context_excerpt": {"source":"url","capsule_id":"...","capsule_version":"...","snippet":"..."},
      "build": {"dist_files":["..."], "hashes_ok": true, "mock_strings_found": 0},
      "api": {
        "status_cached": {"http":200,"as_of":"...","stale":false,"items_preview":2},
        "status_fresh": {"http":200,"as_of_changed": true},
        "refresh_call": {"accepted": true}
      },
      "ui_checks": {
        "basic_auth": "ok",
        "react_bootstrap": "ok|warn|fail",
        "console_errors": 0,
        "legend_present": "planned|present"
      },
      "sla": {"agents_status_cached_ms_p95":"<100"},
      "screens": ["path_or_ref_screenshot_agents"],
      "findings": ["кратко"],
      "status": "green|yellow|red",
      "next_steps": ["кратко"]
    }
  },
  "dod": [
    "UI /admin/agents доступен под Basic Auth; React инициализируется (видны карточки и 'as of').",
    "GET /api/v1/agents/status (fresh=0) < 100 мс; fresh=1 возвращает обновлённый снимок (as_of меняется).",
    "Мок-данных и мок-баннера нет.",
    "Отчёт REPORT_Agents_Cache_UI_Deploy_v1 представлен одним сообщением с пруфами."
  ],
  "guardrails": [
    "не использовать sudo для сборки; запускать штатные обёртки из контекста",
    "секреты получать из secret-store/Кортекса; не писать в логи",
    "если React падает: приложить первую ошибку из консоли и минимальный root-cause"
  ],
  "risks": [
    "Basic Auth недоступен агенту → приложи альтернативные пруфы (dist+assets+network к API) и отметь status='yellow'",
    "кэш не обновляется из-за фоновой задачи → отрази в findings и status='yellow'"
  ]
}
